// UserDao.java
package com.demo;
import java.sql.*;
public class UserDao {
  private static final String URL =
      "jdbc:mysql://localhost:3306/userdb"
      + "?useUnicode=true&characterEncoding=UTF-8";
  // 用户名和密码都正确时返回姓名，否则返回null
  public String check(String u, String p)
      throws Exception {
    Class.forName("com.mysql.jdbc.Driver");
    try (Connection c = DriverManager.getConnection(
        URL, "root", "123456")) {
      PreparedStatement ps = c.prepareStatement(
          "SELECT realname FROM users WHERE"
          + " username = ? AND password = ?");
      ps.setString(1, u);
      ps.setString(2, p);
      ResultSet rs = ps.executeQuery();
      return rs.next() ? rs.getString(1) : null;
    }
  }
}

// LoginServlet.java
package com.demo;
import java.io.*;
import javax.servlet.*;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.*;
@WebServlet("/login")
public class LoginServlet extends HttpServlet {
  protected void doPost(HttpServletRequest req,
      HttpServletResponse resp)
      throws ServletException, IOException {
    req.setCharacterEncoding("UTF-8");
    String u = req.getParameter("username");
    String p = req.getParameter("password");
    String name;
    try {
      name = new UserDao().check(u, p);
    } catch (Exception e) {
      throw new ServletException(e);
    }
    if (name == null) {
      req.setAttribute("msg", "用户名或密码错误");
      req.getRequestDispatcher("/login.jsp")
          .forward(req, resp);
      return;
    }
    HttpSession s = req.getSession();
    s.setAttribute("user", u);
    s.setAttribute("realname", name);
    Cookie ck = new Cookie("uname", u);
    if (req.getParameter("remember") != null) {
      ck.setMaxAge(7 * 24 * 60 * 60);
    } else {
      ck.setMaxAge(0);
    }
    resp.addCookie(ck);
    resp.sendRedirect("user/main.jsp");
  }
}

// LoginFilter.java
package com.demo;
import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;
public class LoginFilter implements Filter {
  private String loginPage;
  public void init(FilterConfig cfg) {
    loginPage = cfg.getInitParameter("loginPage");
  }
  public void doFilter(ServletRequest req,
      ServletResponse resp, FilterChain chain)
      throws IOException, ServletException {
    HttpServletRequest r =
        (HttpServletRequest) req;
    HttpSession s = r.getSession(false);
    if (s != null
        && s.getAttribute("user") != null) {
      chain.doFilter(req, resp);
    } else {
      ((HttpServletResponse) resp).sendRedirect(
          r.getContextPath() + loginPage);
    }
  }
  public void destroy() { }
}
<!-- web.xml（写在<web-app>中） -->
<filter>
  <filter-name>loginFilter</filter-name>
  <filter-class>com.demo.LoginFilter</filter-class>
  <init-param>
    <param-name>loginPage</param-name>
    <param-value>/login.jsp</param-value>
  </init-param>
</filter>
<filter-mapping>
  <filter-name>loginFilter</filter-name>
  <url-pattern>/user/*</url-pattern>
</filter-mapping>

