// MessageDao.java
package com.bean;
import java.sql.*;
import java.util.*;
public class MessageDao {
  private Connection open() throws Exception {
    Class.forName("com.mysql.jdbc.Driver");
    return DriverManager.getConnection(
        "jdbc:mysql://localhost:3306/msgdb"
        + "?useUnicode=true&characterEncoding=UTF-8",
        "root", "123456");
  }
  public void add(Message m) throws Exception {
    try (Connection c = open()) {
      PreparedStatement ps = c.prepareStatement(
          "INSERT INTO message VALUES"
          + "(NULL, ?, ?, ?, NOW())");
      ps.setString(1, m.getAuthor());
      ps.setString(2, m.getTitle());
      ps.setString(3, m.getContent());
      ps.executeUpdate();
    }
  }
  public List<Message> findAll() throws Exception {
    List<Message> list = new ArrayList<>();
    try (Connection c = open()) {
      ResultSet rs = c.createStatement().executeQuery(
          "SELECT * FROM message ORDER BY id DESC");
      while (rs.next()) {
        Message m = new Message();
        m.setAuthor(rs.getString("author"));
        m.setTitle(rs.getString("title"));
        m.setContent(rs.getString("content"));
        m.setPosttime(rs.getTimestamp("posttime"));
        list.add(m);
      }
    }
    return list;
  }
}

// EncodingFilter.java
package com.demo;
import java.io.*;
import javax.servlet.*;
public class EncodingFilter implements Filter {
  private String encoding;
  public void init(FilterConfig cfg) {
    encoding = cfg.getInitParameter("encoding");
    if (encoding == null) encoding = "UTF-8";
  }
  public void doFilter(ServletRequest req,
      ServletResponse resp, FilterChain chain)
      throws IOException, ServletException {
    req.setCharacterEncoding(encoding);
    resp.setCharacterEncoding(encoding);
    chain.doFilter(req, resp);
  }
  public void destroy() { }
}
