// ListServlet.java
package com.demo;
import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.*;
import com.bean.Student;
@WebServlet("/list")
public class ListServlet extends HttpServlet {
  protected void doGet(HttpServletRequest req,
      HttpServletResponse resp)
      throws ServletException, IOException {
    String key = req.getParameter("key");
    if (key == null) key = "";
    List<Student> list = new ArrayList<>();
    try (Connection c = DBUtil.getConnection()) {
      PreparedStatement ps = c.prepareStatement(
          "SELECT * FROM student WHERE sname"
          + " LIKE ? ORDER BY sno");
      ps.setString(1, "%" + key.trim() + "%");
      ResultSet rs = ps.executeQuery();
      while (rs.next()) {
        Student s = new Student();
        s.setSno(rs.getString("sno"));
        s.setSname(rs.getString("sname"));
        s.setSex(rs.getString("sex"));
        s.setAge(rs.getInt("age"));
        list.add(s);
      }
    } catch (Exception e) {
      throw new ServletException(e);
    }
    req.setAttribute("list", list);
    req.getRequestDispatcher("/list.jsp")
        .forward(req, resp);
  }
}

// AddServlet.java
package com.demo;
import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.*;
@WebServlet("/add")
public class AddServlet extends HttpServlet {
  protected void doPost(HttpServletRequest req,
      HttpServletResponse resp)
      throws ServletException, IOException {
    req.setCharacterEncoding("UTF-8");
    try (Connection c = DBUtil.getConnection()) {
      PreparedStatement ps = c.prepareStatement(
          "INSERT INTO student VALUES(?, ?, ?, ?)");
      ps.setString(1, req.getParameter("sno"));
      ps.setString(2, req.getParameter("sname"));
      ps.setString(3, req.getParameter("sex"));
      ps.setInt(4, Integer.parseInt(
          req.getParameter("age").trim()));
      ps.executeUpdate();
    } catch (SQLIntegrityConstraintViolationException e) {
      req.setAttribute("msg", "学号已存在");
      req.getRequestDispatcher("/add.jsp")
          .forward(req, resp);
      return;
    } catch (Exception e) {
      throw new ServletException(e);
    }
    resp.sendRedirect("list");
  }
}

// CheckFilter.java
package com.demo;
import java.io.*;
import javax.servlet.*;
import javax.servlet.annotation.WebFilter;
@WebFilter("/add")
public class CheckFilter implements Filter {
  public void init(FilterConfig cfg) { }
  public void doFilter(ServletRequest req,
      ServletResponse resp, FilterChain chain)
      throws IOException, ServletException {
    req.setCharacterEncoding("UTF-8");
    String sno = req.getParameter("sno");
    String name = req.getParameter("sname");
    int age = -1;
    try {
      age = Integer.parseInt(
          req.getParameter("age").trim());
    } catch (Exception e) { }
    String msg = null;
    if (sno == null || !sno.matches("\\d{7}")) {
      msg = "学号应为7位数字";
    } else if (name == null
        || name.trim().isEmpty()) {
      msg = "姓名不能为空";
    } else if (age < 15 || age > 60) {
      msg = "年龄应为15～60的整数";
    }
    if (msg == null) {
      chain.doFilter(req, resp);
    } else {
      req.setAttribute("msg", msg);
      req.getRequestDispatcher("/add.jsp")
          .forward(req, resp);
    }
  }
  public void destroy() { }
}

