package com.bean;
public class CartItem implements java.io.Serializable {
  private int id, qty;
  private String name;
  private double price;
  public int getId() { return id; }
  public void setId(int i) { id = i; }
  public String getName() { return name; }
  public void setName(String s) { name = s; }
  public double getPrice() { return price; }
  public void setPrice(double p) { price = p; }
  public int getQty() { return qty; }
  public void setQty(int q) { qty = q; }
  public double getSubtotal() { return price * qty; }
}

// Cart.java
package com.bean;
import java.util.*;
public class Cart implements java.io.Serializable {
  private Map<Integer, CartItem> items =
      new LinkedHashMap<>();
  // 已有同一商品时只增加数量
  public void add(CartItem it) {
    CartItem old = items.get(it.getId());
    if (old == null) {
      items.put(it.getId(), it);
    } else {
      old.setQty(old.getQty() + it.getQty());
    }
  }
  public void remove(int id) { items.remove(id); }
  public void clear() { items.clear(); }
  public Collection<CartItem> getItems() {
    return items.values();
  }
  public boolean isEmpty() {
    return items.isEmpty();
  }
  public double getTotal() {
    double t = 0;
    for (CartItem it : items.values()) {
      t += it.getSubtotal();
    }
    return t;
  }
}
